public void ApplyFrmPermission(object frm)
        {
            if (frm == null)
                return;

            if (frm is System.Windows.Window window)
            {
                ApplyFrmPermissionInternal(window);
                return;
            }

            if (frm is FrameworkElement frameworkElement)
            {
                ApplyFrmPermissionInternal(frameworkElement);
                return;
            }
        }

